\u006a\u0079\u0065\u0062\u0034\u002c\u004a\u0064\u0066\u006d\u0032\u003c\u005b\u0040\u0047\u0026\u003a\u0075\u003f\u0043\u0037\u002b\u003b\u005e\u003f\u0033\u0055\u004d\u002a\u003a\u003a\u0074\u0028\u0025\u004e\u0035\u0042\u0075\u0069\u0024\u006c\u004d\u0040\u003f\u002c\u004e\u0047\u002f\u0072\u004f\u0047\u0053\u005b\u003a\u0051\u004f\u0028\u004c\u0062\u0052\u007c\u0049\u0024\u005f\u0078\u0061\u0045\u0048\u0036\u004e\u0063\u0024\u0028\u0052\u0035\u007d\u0055\u0063\u003b\u006b\u003e\u0039\u0028\u0024\u004c\u0066\u007a\u0021\u006d\u0042\u0073\u006b\u0069\u0044\u003e\u004d\u0022\u004d\u004c\u0053\u0077\u0035\u003c\u0042\u0029\u0069\u0064\u007c\u005f\u003e\u003d\u0022\u007c\u0045\u005e\u003a\u005a\u006a\u006e\u0046\u007d\u0077\u003e\u002c\u007b\u0066\u005e\u0075\u003c\u0034\u0075\u0030\u0045\u0023\u0040\u0043\u0059\u0077\u0050\u0047\u007a\u005d\u003d\u0036\u0038\u003f\u003e\u0029\u004f\u0030\u0046\u003a\u0037\u0069\u006f\u0054\u0022\u0067\u0052\u002b\u0048\u0070\u0038\u0028\u0043\u0044\u0059\u0059\u005e\u0075\u0077\u0037\u0075\u003a\u0072\u0046\u0065\u0073\u006b\u0076\u006f\u0028\u0028\u0058\u004d\u002a\u007a\u004d\u0025\u0039\u0033\u0074\u0063\u0079\u0040\u003f\u0070\u003a\u003b\u0028\u006d\u0031\u0058\u0059\u0059\u005e\u0075\u0077\u0037\u004a\u0028\u004a\u004d\u0041\u0056\u0056\u0021\u0040\u003b\u006b\u007b\u006b\u0060\u0035\u002a\u0031\u0039\u0028\u0028\u0079\u006d\u0023\u0040\u007a\u003d\u0061\u0049\u0047\u0066\u006f\u003d\u004b\u0054\u0025\u0050\u0023\u0055\u0044\u0046\u0040\u002f\u0061\u002f\u005b\u0075\u0060\u003a\u0046\u0040\u0071\u0069\u0059\u002f\u0061\u007a\u006c\u0060\u0078\u0077\u0078\u0024\u004b\u0023\u0050\u0032\u0044\u0025\u0068\u003c\u0075\u0043\u0037\u002b\u0021\u0071\u007b\u0025\u0041\u007d\u007b\u002c\u002b\u0039\u004d\u0072\u005f\u0022\u0052\u002f\u007a\u003f\u0064\u004f\u0029\u0032\u002f\u003c\u0044\u0029\u0056\u0031\u002f\u0025\u0046\u002e\u002b\u0048\u004d\u002c\u0028\u0049\u003b\u0042\u004e\u0026\u007d\u0044\u0044\u007a\u0031\u0047\u002e\u007d\u0055\u0057\u0023\u006a\u005b\u0073\u0042\u0030\u0044\u006e\u0069\u0044\u0028\u0043\u0077\u0040\u0057\u0064\u002c\u0028\u0075\u0035\u0071\u007e\u0076\u0077\u0032\u004d\u0058\u0072\u006c\u0068\u002e\u004e\u006f\u0049\u007a\u007e\u0028\u0037\u0046\u0024\u002a\u003e\u0067\u002e\u0045\u0045\u002e\u003b\u0063\u0071\u0037\u004e\u0037\u0046\u0022\u005a\u004d\u004d\u003b\u0069\u005a\u0051\u0066\u0022\u0052\u0041\u0022\u0066\u005e\u0064\u005e\u0075\u0056\u0023\u0067\u0050\u004b\u004b\u006d\u002c\u003e\u004d\u004d\u0051\u0037\u005e\u0074\u0023\u007d\u0051\u0046\u007e\u007a\u006f\u0072\u0065\u0069\u006f\u003c\u006f\u0068\u0033\u007b\u002a\u0026\u0064\u0060\u006c\u006b\u0056\u0021\u005f\u0078\u0045\u0066\u0074\u007e\u0030\u0055\u0033\u007b\u0043\u0053\u006c\u007a\u006d\u003e\u0063\u0073\u0035\u004b\u002c\u0065\u003e\u0039\u006e\u0055\u0029\u006b\u0077\u0059\u0070\u0021\u005d\u0021\u0051\u0057\u0076\u0056\u0047\u006b\u007d\u0060\u0039\u0076\u002a\u0040\u004e\u0074\u006c\u002c\u0035\u006d\u002b\u007e\u0022\u0061\u006b\u0072\u005b\u0055\u005b\u0071\u0079\u002f\u0075\u0023\u006b\u004a\u0046\u0063\u0023\u006e\u002a\u0026\u0021\u0048\u0055\u005d\u0023\u0062\u007b\u003b\u002f\u003d\u0045\u0068\u004f\u006f\u0026\u0076\u0053\u0050\u0057\u007c\u003a\u006e\u0070\u0028\u0055\u0052\u0026\u0054\u0076\u0065\u0040\u005a\u002a\u0059\u0036\u0060\u0066\u0030\u0029\u006e\u0031\u006e\u0026\u0058\u0056\u005e\u003f\u0070\u0067\u005f\u003e\u0030\u006a\u0023\u0066\u0045\u007a\u0050\u0047\u0064\u0060\u006c\u005d\u007d\u0071\u0053\u0055\u0037\u003d\u0064\u0070\u0054\u006f\u0061\u0073\u002c\u0029\u006c\u006d\u0033\u002a\u0043\u003e\u003b\u006a\u0072\u0029\u0028\u007b\u0044\u0045\u0044\u005b\u0063\u002c\u007a\u0074\u0054\u003a\u0031\u003d\u0051\u0046\u003c\u0055\u0022\u0077\u002b\u0055\u004d\u006d\u0033\u002a\u0033\u0078\u0033\u007d\u007e\u0065\u0037\u0028\u004f\u0037\u005b\u0072\u0033\u0053\u004c\u0037\u0029\u006f\u0057\u0026\u005b\u0064\u0036\u0033\u0031\u0070\u0067\u004a\u0039\u007c\u007d\u006d\u0034\u0028\u0058\u0073\u003a\u0078\u0059\u0066\u003d\u0041\u003e\u0058\u0028\u0036\u003d\u0064\u0070\u0034\u006f\u002f\u0035\u0055\u004a\u0039\u005f\u0046\u006a\u0063\u006f\u0034\u0051\u0022\u005b\u0042\u003a\u002c\u0065\u006a\u0058\u0038\u006b\u007b\u0046\u005a\u0061\u002b\u004c\u002c\u002a\u006a\u0046\u0063\u0047\u0058\u0047\u007e\u005a\u003e\u003b\u0057\u0059\u006d\u006e\u0031\u0056\u0069\u0039\u0049\u0079\u0071\u0061\u0073\u0079\u0022\u0045\u003c\u004b\u003a\u0025\u003e\u0021\u003d\u0029\u002c\u003c\u0060\u0073\u006a\u0068\u0025\u0053\u006f\u006f\u003c\u005a\u007c\u0021\u0054\u0025\u003f\u002e\u007b\u0022\u0064\u0053\u007e\u0053\u004f\u003c\u0033\u004e\u0040\u0072\u004a\u0052\u0056\u002f\u0057\u0043\u0045\u0068\u0072\u0049\u0050\u0025\u004f\u0038\u007a\u0047\u0073\u0026\u004f\u0026\u005a\u003d\u0038\u002e\u006d\u0022\u0063\u0073\u0036\u004e\u002b\u005e\u0066\u006f\u006a\u0060\u0041\u007c\u003d\u006f\u0022\u0030\u007d\u0058\u004c\u0031\u0058\u002f\u0046\u006e\u003e\u007e\u0036\u004b\u0039\u003e\u003f\u0045\u0047\u005e\u0045\u002a\u0060\u0030\u006b\u0046\u0028\u0030\u0044\u005f\u0078\u0028\u007e\u002e\u0047\u006c\u002e\u0042\u006f\u0034\u004a\u0055\u0074\u0054\u0077\u0064\u0068\u0047\u0037\u0062\u0033\u006a\u0042\u0046\u002a\u0064\u005d\u004a\u0065\u0062\u0079\u0026\u0038\u0028\u0037\u0067\u0026\u0054\u0066\u0078\u0038\u0060\u0071\u0071\u004e\u0029\u002c\u0024\u0069\u0034\u0061\u0070\u0071\u004c\u0039\u002a\u0046\u004f\u0021\u0065\u0024\u0066\u003a\u003f\u007a\u0048\u005b\u0071\u0026\u0069\u0045\u0063\u003f\u005e\u002b\u0029\u005e\u003d\u005e\u0075\u0072\u0049\u0064\u002f\u004e\u0078\u0059\u006c\u0028\u0072\u006e\u0063\u0074\u007b\u0052\u002f\u0031\u007d\u0041\u0056\u0039\u005f\u003e\u005d\u0035\u007c\u0022\u0072\u007a\u005b\u004f\u003e\u0055\u006f\u0050\u0046\u0034\u0036\u0043\u007e\u005d\u002b\u0054\u0022\u006d\u0072\u0052\u0065\u0078\u0035\u0031\u0037\u0032\u0060\u0066\u0044\u0078\u006f\u006c\u0022\u0026\u0078\u0079\u0021\u0030\u0071\u004e\u002c\u0059\u0058\u005e\u003b\u0070\u004e\u002e\u0052\u0050\u0055\u0035\u003c\u0066\u0048\u0061\u0044\u0035\u004c\u006f\u003f\u0048\u004f\u0024\u0056\u0055\u0029\u007b\u0069\u004c\u0042\u0051\u0054\u006c\u0022\u007c\u006f\u005d\u0037\u005f\u0050\u007d\u0045\u0039\u002f\u0022\u003b\u0070\u004e\u002e\u0052\u0050\u0067\u0036\u007a\u005b\u0055\u0076\u0035\u0059\u002a\u0067\u007c\u0066\u0047\u0026\u0078\u0040\u0075\u0021\u0047\u0043\u004c\u0028\u006a\u0048\u005e\u004b\u0075\u004f\u0038\u005a\u0022\u006a\u004d\u002c\u0026\u0043\u0046\u006b\u0032\u006f\u004b\u005a\u005a\u0047\u002e\u0065\u0068\u004e\u0043\u0032\u002b\u005b\u0079\u002e\u004c\u002c\u0047\u0025\u0038\u003f\u003f\u0069\u0054\u0076\u002e\u0051\u0071\u0075\u0059\u007b\u0070\u006b\u0039\u0062\u0038\u0028\u0031\u0064\u0059\u0069\u002c\u0043\u007c\u006f\u006e\u006c\u0029\u004e\u0023\u0024\u0023\u0050\u003c\u006b\u0052\u0044\u007e\u0076\u0029\u0024\u003b\u0059\u0036\u005e\u0065\u003b\u003f\u0033\u0067\u0046\u0043\u004c\u004d\u0058\u0034\u0055\u0066\u0031\u004a\u0052\u0075\u0037\u0031\u0068\u004b\u003e\u0062\u003c\u0023\u004d\u0026\u007c\u0073\u0061\u0035\u0047\u0048\u0070\u007b\u0076\u0058\u0034\u0025\u0069\u0079\u0022\u0074\u003e\u0042\u0079\u0033\u0068\u003b\u0048\u0079\u0070\u0056\u0072\u0055\u0066\u006a\u003d\u004e\u0051\u0076\u0060\u003f\u003a\u006d\u0045\u0049\u0034\u003f\u006d\u006c\u0055\u0051\u003e\u0039\u0029\u003c\u0040\u0052\u0047\u006d\u0021\u0053\u0069\u0033\u005e\u002f\u0074\u0042\u003f\u0032\u0067\u0025\u0065\u004e\u0049\u0049\u0072\u0068\u0021\u005b\u0031\u0051\u0044\u0046\u004d\u0028\u0068\u0076\u0068\u0067\u006f\u004e\u0061\u002c\u006c\u005d\u0056\u0051\u0023\u0041\u0058\u007c\u004a\u0045\u0040\u0034\u005f\u0038\u0022\u0052\u0051\u003c\u0059\u0041\u0071\u004d\u0042\u007a\u005d\u002a\u0023\u0051\u004e\u0039\u0067\u0031\u0042\u002a\u0038\u0058\u0048\u0060\u0069\u003e\u0056\u0062\u0077\u0022\u0041\u0064\u0053\u0021\u0075\u007a\u0059\u0062\u004d\u0045\u006b\u007e\u007e\u0065\u004a\u0069\u0065\u0058\u0048\u0031\u003b\u0062\u0034\u0074\u004f\u0074\u0042\u0046\u002a\u0064\u005d\u004a\u005b\u0058\u0070\u0046\u0025\u007d\u0070\u0033\u0074\u002f\u0042\u0046\u002a\u0064\u005d\u004a\u005b\u0058\u0031\u0074\u0063\u0040\u0056\u006d\u0053\u007a\u006c\u0079\u0076\u0070\u004e\u0058\u003c\u0025\u0042\u0046\u002a\u0064\u005d\u004a\u005b\u0058\u003b\u0030\u0056\u003c\u006b\u0023\u007a\u004b\u0038\u0028\u0025\u0050\u0069\u004a\u0066\u003e\u007a\u003a\u0025\u003b\u003b\u004f\u005d\u0061\u0064\u0032\u0055\u007e\u0070\u0074\u0060\u0078\u0071\u002f\u0072\u0070\u006d\u0065\u002f\u0056\u003c\u0044\u005f\u0065\u003a\u002a\u0079\u0076\u0071\u0035\u0078\u0024\u0035\u006d\u0071\u0068\u005e\u007e\u005d\u004a\u006a\u0067\u002a\u007d\u0072\u005e\u0031\u0037\u0040\u0056\u0070\u006d\u0065\u002f\u0056\u0062\u0064\u004b\u0052\u0078\u0034\u0065\u003b\u0038\u004a\u0069\u003c\u002a\u0023\u002c\u0071\u0077\u0025\u002a\u0058\u0062\u003f\u007a\u0044\u007e\u0047\u003d\u004a\u0028\u0072\u0063\u0021\u0051\u005d\u006b\u0045\u0068\u0058\u0066\u0029\u0054\u0057\u0059\u004d\u006f\u0051\u005d\u005a\u002f\u0069\u004d\u0046\u005d\u0068\u0079\u003d\u0077\u0052\u0033\u0046\u0033\u0070\u007b\u0058\u004b\u0052\u006e\u0046\u0039\u0049\u0059\u004e\u003b\u0072\u0035\u007c\u0077\u002a\u005b\u0026\u0054\u002b\u005d\u005d\u003e\u0022\u004c\u0073\u004a\u0037\u0077\u0021\u006d\u0048\u006f\u0028\u0074\u0045\u0073\u0076\u003e\u0044\u0049\u007b\u002c\u007b\u0067\u0037\u0071\u002f\u0049\u0075\u0049\u0051\u0055\u003b\u0072\u0047\u0023\u0057\u0028\u0026\u0040\u0025\u003c\u0067\u002f\u007d\u0036\u004a\u0071\u0048\u003d\u0029\u0037\u0063\u007a\u005e\u007d\u004c\u0050\u004e\u0052\u005d\u0056\u004f\u0079\u0064\u004e\u007b\u0064\u002e\u002f\u0075\u0044\u0071\u0042\u0070\u0048\u003d\u0074\u0076\u0040\u0038\u007d\u007b\u003b\u004f\u0079\u0078\u0054\u0061\u0043\u0048\u0045\u0077\u006e\u0068\u0040\u0029\u0036\u0032\u003b\u0026\u0024\u0068\u006e\u0029\u004e\u0024\u003c\u006f\u0067\u003e\u0025\u004f\u0068\u006b\u0056\u002a\u0034\u0079\u0029\u006c\u005f\u0037\u007e\u0023\u0078\u0078\u0067\u002e\u005f\u0021\u003b\u0074\u0051\u0024\u0029\u0026\u006d\u0042\u005f\u0071\u0024\u0028\u0064\u0028\u004f\u0066\u005a\u0052\u0022\u0026\u003d\u0024\u002b\u0034\u0041\u0048\u0048\u007b\u0064\u0045\u0051\u0060\u0053\u0044\u0026\u003f\u0061\u0072\u0047\u0023\u0037\u0042\u0071\u0068\u0055\u0022\u0075\u003b\u003a\u0056\u0044\u0060\u0031\u002b\u0046\u0048\u0046\u002e\u002c\u0073\u002b\u002f\u0044\u0049\u006c\u004e\u002b\u006f\u005d\u004f\u002a\u005b\u0050\u0067\u007e\u006c\u0077\u006f\u002c\u002a\u007b\u0066\u005d\u002f\u002c\u0024\u007d\u0037\u002e\u004e\u0066\u002c\u004a\u002c\u0050\u0049\u0030\u0029\u003b\u003d\u007e\u006d\u007b\u0040\u0048\u007d\u0068\u0068\u0072\u005e\u0026\u0040\u0066\u0072\u005a\u002f\u003f\u0057\u0059\u0069\u0035\u004b\u0021\u0039\u0066\u0069\u0071\u003b\u0077\u002b\u0061\u0072\u0048\u0046\u004e\u0040\u0029\u007d\u006b\u0073\u0044\u007a\u004b\u0023\u0058\u0050\u0075\u002b\u0078\u0038\u0078\u0055\u0050\u0067\u007e\u006c\u006f\u0071\u006a\u003e\u006f\u0037\u003c\u0028\u0030\u0060\u0079\u0073\u007b\u007d\u0045\u0028\u0037\u005e\u006c\u003e\u007c\u0039\u0069\u0054\u0034\u0024\u006c\u0047\u0075\u004f\u0021\u005d\u0050\u003f\u0071\u002b\u0048\u003a\u0075\u0029\u005d\u0059\u003e\u0059\u007b\u003d\u006d\u0024\u0069\u0041\u003e\u0055\u0033\u002a\u0075\u0023\u0065\u0052\u0036\u0034\u0049\u0066\u0073\u0048\u0033\u006d\u0048\u0064\u0079\u003b\u0059\u0079\u003a\u0062\u005b\u0040\u0078\u0026\u0068\u0068\u004a\u007b\u006c\u007c\u007b\u0066\u0067\u0077\u0037\u0057\u002f\u0073\u0067\u0054\u0023\u005f\u0049\u0036\u0073\u0072\u005d\u0072\u0076\u005e\u0060\u006f\u0041\u002f\u0048\u0052\u0061\u006f\u0036\u0077\u003a\u0052\u002e\u0078\u0037\u0045\u004f\u0079\u0074\u0048\u0076\u007c\u0061\u0040\u002b\u0021\u0045\u0079\u004f\u0048\u005e\u003a\u0056\u0073\u0032\u0021\u0045\u0072\u004a\u0077\u0029\u0063\u0048\u004a\u0052\u0066\u006e\u006b\u0068\u0079\u0040\u0026\u006c\u0046\u0070\u0055\u0070\u0039\u0071\u0059\u0048\u0029\u002e\u0050\u005f\u0026\u0075